class Solution {
public:
    int checkWays(vector<vector<int>>& pairs) {
        unordered_map<int, unordered_set<int>> adj;
        for (const auto& p : pairs) {
            adj[p[0]].insert(p[1]);
            adj[p[1]].insert(p[0]);
        }
        for (auto& [u, neighbors] : adj) {
            neighbors.insert(u);
        }
        int n = adj.size();
        bool hasRoot = false;
        for (const auto& [u, neighbors] : adj) {
            if (neighbors.size() == n) {
                hasRoot = true;
                break;
            }
        }
        if (!hasRoot) return 0;
        vector<int> nodes;
        for (const auto& [u, _] : adj) nodes.push_back(u);
        sort(nodes.begin(), nodes.end(), [&](int a, int b) {
            return adj[a].size() < adj[b].size();
        });
        bool multiple = false;
        for (int u : nodes) {
            int parent = -1;
            int minDeg = 1e9;
            for (int v : adj[u]) {
                if (v != u && adj[v].size() >= adj[u].size() && (int)adj[v].size() < minDeg) {
                    minDeg = adj[v].size();
                    parent = v;
                }
            }
            if (parent != -1) {
                for (int x : adj[u]) {
                    if (!adj[parent].count(x)) return 0;
                }
                if (adj[u].size() == adj[parent].size()) multiple = true;
            }
        }
        return multiple ? 2 : 1;
    }
};

class Solution {
    public int checkWays(int[][] pairs) {
        Map<Integer, Set<Integer>> adj = new HashMap<>();
        for (int[] p : pairs) {
            adj.computeIfAbsent(p[0], k -> new HashSet<>()).add(p[1]);
            adj.computeIfAbsent(p[1], k -> new HashSet<>()).add(p[0]);
        }
        for (var entry : adj.entrySet()) {
            entry.getValue().add(entry.getKey());
        }
        int n = adj.size();
        boolean hasRoot = false;
        for (var set : adj.values()) {
            if (set.size() == n) {
                hasRoot = true;
                break;
            }
        }
        if (!hasRoot) return 0;
        List<Integer> nodes = new ArrayList<>(adj.keySet());
        nodes.sort(Comparator.comparingInt(a -> adj.get(a).size()));
        boolean multiple = false;
        for (int u : nodes) {
            int parent = -1;
            int minDeg = Integer.MAX_VALUE;
            for (int v : adj.get(u)) {
                if (v != u && adj.get(v).size() >= adj.get(u).size() && adj.get(v).size() < minDeg) {
                    minDeg = adj.get(v).size();
                    parent = v;
                }
            }
            if (parent != -1) {
                if (!adj.get(parent).containsAll(adj.get(u))) {
                    return 0;
                }
                if (adj.get(u).size() == adj.get(parent).size()) {
                    multiple = true;
                }
            }
        }
        return multiple ? 2 : 1;
    }
}

var checkWays = function(pairs) {
    const adj = new Map();
    for (const [u, v] of pairs) {
        if (!adj.has(u)) adj.set(u, new Set());
        if (!adj.has(v)) adj.set(v, new Set());
        adj.get(u).add(v);
        adj.get(v).add(u);
    }
    for (const [u, set] of adj) {
        set.add(u);
    }
    const n = adj.size();
    let hasRoot = false;
    for (const [u, set] of adj) {
        if (set.size() === n) {
            hasRoot = true;
            break;
        }
    }
    if (!hasRoot) return 0;
    const nodes = Array.from(adj.keys()).sort((a, b) => adj.get(a).size - adj.get(b).size);
    let multiple = false;
    for (const u of nodes) {
        let parent = -1;
        let minDeg = Infinity;
        for (const v of adj.get(u)) {
            if (v !== u && adj.get(v).size >= adj.get(u).size && adj.get(v).size < minDeg) {
                minDeg = adj.get(v).size;
                parent = v;
            }
        }
        if (parent !== -1) {
            for (const x of adj.get(u)) {
                if (!adj.get(parent).has(x)) return 0;
            }
            if (adj.get(u).size === adj.get(parent).size) {
                multiple = true;
            }
        }
    }
    return multiple ? 2 : 1;
};
